AND TO_DAYS(NOW()) - TO_DAYS(a.create_time) = 0
AND TO_DAYS(NOW()) - TO_DAYS(a.create_time) = 1
AND DATE_FORMAT(a.create_time, '%Y%m') = DATE_FORMAT(CURDATE(), '%Y%m')
${params.dataScope}

SELECT DATE_FORMAT(a.create_time,'%Y-%m-%d') days,count(a.id) number FROM phone_member a left join sys_dept d on a.dept_id = d.dept_id
DATE_FORMAT(a.create_time, '%Y-%m') = DATE_FORMAT(CURRENT_DATE, '%Y-%m')
AND a.app_id = #{appId}
${params.dataScope}
group by days

